#!/usr/bin/env python3
"""Inline local assets; embeds SVGs too, so the export has no local-file links."""
import argparse,pathlib,re,json,base64,hashlib,mimetypes
ROOT=pathlib.Path(__file__).resolve().parent
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--output',type=pathlib.Path,default=ROOT.parent/'ScienceGym-Task-Explorer.html')
args=parser.parse_args()
page=(ROOT/'index.html').read_text()
route_count=sum(f['routes'] for f in json.loads((ROOT/'manifest.json').read_text())['families'])
page=page.replace('<link rel="stylesheet" href="styles.css">','<style>'+(ROOT/'styles.css').read_text()+'</style>')
for name in ['README.md','docs/ADAPTERS.md']:page=page.replace('href="'+name+'"','href="#standaloneGuide"')
page=page.replace('<footer>', '<details id="standaloneGuide"><summary>Offline guide and verification boundary</summary><div><p>Choose a family and branch, then click an operation. Search highlights matches without hiding route steps. Use Dependencies &amp; choices for declared partial orders and Acceptance &amp; unknowns for evaluator contracts.</p><p>Source scientific stages and authored robot handling remain distinct. Arrows indicate reference list order. Loops are unexpanded contracts; repeated IDs retain their occurrence index. Acquisition, data, cooling, EmVP and prismatic membership obligations do not imply unspecified chronology. Prismatic material/target and thickness/target nesting remains symbolic; null counts block expansion. EmVP cage conditions retain separate source routes, and comparison coverage never converts states or sites into independent specimens.</p><p>SVG overview downloads the embedded diagram for the selected family. Earlier-family source links open pinned public snapshots. The eleven recent families embed their exact local source JSON and original asset guide/render bytes; opening an embedded file does not assert remote publication. Cooling retains six symbolic loop contracts, conditional receipt gates, unknown counts and required physical transfer instances. Mechanical views preserve typed forward/adjoint bindings, physical transfers, ring concurrency and conditional preparation. Numerical training is not physical self-updating, and ring torque is semi-experimental rather than directly measured. Proposals and source-missing gates retain their source-specific status. Assembly views preserve scoped granular/thermal dependency gates, symbolic repeats, actual sample/packing lineage and separate device ownership. Beaded exclusive preparation choices and typed loop bindings remain unselected templates. Source-section navigation counts do not create new experiments. Final materials views preserve Horn matched-map and numerical distinctions, ReMM source_complete=false with unread panels/movies, and cold-shape closed qualified hazardous services. Derived fits never become independent validation. Condition schedules, loops and sample counts remain symbolic. Gear recipes retain authored order, separate preparation/condition templates, specimen identities and unresolved geometry conflicts. Numerical operations and illustrative demonstrations never gain physical credit. Hydrogel memberships retain per-service phase order without cross-service chronology; four Extended Data image sets remain uninspected, power/data conflicts remain open, Video 9 is accelerated 20 times, and all hazardous processes remain closed qualified services. Cross-disciplinary views preserve atmospheric mount leases and observed/simulated data separation; AFM bounded imaging, retained probes, target exchange and final teardown; Martian closed facility services and sample/region lineage; and transistor unordered inventories, lifecycle, typed cohorts, safe zero and unresolved conflicts. Incomplete fabrication and prospective records never earn physical completion. The explorer distinguishes 41 paper-level designs and three bounded subsets. Paired views preserve qualification/flow/direction hold defaults and exact profile/lineage/exclusion contracts, and link existing original 3D guides/static renders without interactive web physics. Woven retains 24 scientific routes plus a separate qualification-hold view, 48 symbolic operations, 11 static groups and 43 symbolic anchors. The source suite reports 96 synthetic configurations; the viewer preserves their count and JSON contracts. Lockable origami adds 30 source branches plus four hold views; varactor adds 28 source branches plus a default hold. Source memberships, conditional recovery, fabrication/intake ancestry, open-path origami work, varactor shared-specimen revisions and source access gaps stay explicit. Wetting adds sixteen design routes plus a metadata-only qualification hold; cadmium fiducial preparation and high-voltage deposition stay external closed boundaries. Six movie samples are not full playback and workbook numerical cells remain unread. Arc-Morph adds seven physical route families, two auxiliary records, six nonmanual dispositions and a metadata-only qualification hold. Its thirty-one operation templates retain repeated transport occurrences and separate phase bodies; one symbolic same-specimen loop keeps eight configuration slots without inventing repeats. Fixture-specific closeout alternatives stay conditional, ten source conflicts and fourteen unknowns stay open, and original static geometry remains illustrative. Mid-infrared adds eight experimental branches, twenty-two authored operation templates, five separate reference views and a metadata-only qualification hold. All controls, lineage, failed attempts and supported holds remain exact. Approximately 10 Hz is confined to analog 16x16, fourteen qualification gaps stay open, and raw data and modified source code remain unavailable. Conformal elasticity adds nine source-scope branches, including two physical experimental designs, sixteen authored templates and a default qualification hold. Numerical and analytical branches remain unexecuted. All five conflicts and sixteen execution gaps stay open; Zenodo archive contents remain unread. Scattering adds five experimental branches and four numerical-review extensions, three preparation/calibration branches and authored closeout, with fourteen symbolic operations, eleven static groups, thirty-two anchors, eight ambiguities and sixteen unknown groups. Acoustic actuation and physical execution remain closed. Additional supporting data remain unread. QHA adds fifteen stages, eleven scene groups and thirty-two anchors; each 118-element subarray is approximately 109 ohm, while the whole 236-element series device is approximately 219 ohm. Twenty-nine facts, eighteen ambiguities and fourteen reported outcomes remain reference material, never generated telemetry. Microfabrication, cryogenics, fields and precision instruments remain closed services. Thermal meta-devices add twenty stages, twelve parent and twelve child scopes, six X/Y views of three device families and separate default/service-custody holds. All nine source conflicts remain open; numerical branches are unexecuted, profiles are qualified obligations and source results never become telemetry. A 45-minute interval or software stop never establishes safe release. Microsphere imaging adds thirteen stages, thirteen source-scope branches, seven stations, nine original scene groups and thirty-three evidence-only anchors. All sixteen qualification gaps remain held; actual-size context and magnified illustrations stay separate. Figure-backed 50 nm gold/AAO transmission remains distinct from text-only cross-mode claims. Star composition and sphere size remain unresolved. SEM, preparation, sphere contact and optical acquisition stay closed services. Source outcomes never become measured results or thresholds. Source rights remain restricted: free-to-read does not establish reuse rights, and no publisher media are embedded. Frictional-fluid design adds twelve evidence routes, nine source branches, six stations, eight original scene groups and thirty-two evidence-only anchors. All twenty physical holds remain unresolved. Coral-rate and Boyle-law conflicts are retained without silently choosing a rate or repairing a formula. Viscosity and high-filling granular fracture remain required separate branches; borrowed porous-medium imagery is attributed context and analytical scope is unimplemented. Per-job R11 closeout may precede aggregate analysis while other jobs remain open; R12 requires all registered jobs closed. Source CC BY-NC-SA 3.0 and third-party rights remain distinct from original Apache-2.0 materials. No pressure command, fluid model, raw-data reproduction or measured scientific result is supplied. These are whole-paper design records, not reproduction. Source conflicts, closed service qualification, independent receipts, physical/model separation and prepared-intake lineage remain exact. This file has no external runtime dependencies.</p><p>Verified: source-equality and structural tests, all CURRENT_ROUTE_COUNT route views in a mocked DOM, portable SVG rendering. Not verified: actual browser rendering, touch/responsive layout or scientific/robot execution. No current real-browser verification is claimed.</p></div></details><footer>')
page=page.replace('CURRENT_ROUTE_COUNT',str(route_count))
svgs={f.stem:f.read_text() for f in (ROOT/'diagrams').glob('*.svg')}
def script_escape(s):return re.sub(r'</script',r'<\\/script',s,flags=re.I)
embedded={}
for entry in json.loads((ROOT/'manifest.json').read_text())['families']:
    f=json.loads((ROOT/'data'/(entry['id']+'.json')).read_text())
    if f.get('source_link_mode')!='repository_relative_frozen_local_snapshot': continue
    for item in list(f['source_files'].values())+f['asset_links']:
        url=item['url']; local=(ROOT/url).resolve()
        local.relative_to(ROOT.parent.parent.resolve())
        payload=local.read_bytes()
        if hashlib.sha256(payload).hexdigest()!=item['sha256']: raise ValueError('Embedded source/asset hash mismatch: '+url)
        embedded[url]={'mime':mimetypes.guess_type(local.name)[0] or 'application/octet-stream',
                       'base64':base64.b64encode(payload).decode('ascii')}
page=page.replace('<script src="app.js"></script>','<script>window.SCIENCEGYM_EMBEDDED_FILES='+script_escape(json.dumps(embedded,separators=(',',':')))+';</script><script src="app.js"></script>')
page=page.replace('<script src="app.js"></script>','<script>window.SCIENCEGYM_SVGS='+script_escape(json.dumps(svgs,ensure_ascii=False))+';</script><script src="app.js"></script>')
page=re.sub(r'<script src="([^"]+)"></script>',lambda m:'<script>'+script_escape((ROOT/m.group(1)).read_text())+'</script>',page)
out=args.output;out.write_text(page)
assert not re.search(r'(?:src|href)="(?!https?:|#)(?!\s*$)[^"]+"',page), 'Unresolved local link'
print(out, out.stat().st_size)
